        MN_SLOTS(MN_SLOT_BIAS)
        MN_CELLS(MN_BIAS)
    }

    MN_CELLS(MN_TOTAL)
    if (subgroupElect()) {
        MN_CELLS(MN_WRITE)
    }
}
